# $ret=  1 vale OK : se lo stato del job e\'  \'done\' e se la date extractlow < extracthigh  --> il job puo\' essere eseguito 

#=============================================================================

#Print (\'DEBUG F.0 AW_CtrlJob --> get status for jobname= {$jobname} \');
$ret = 0;

# get status about previous run
try
    begin
	    #$JobStatus = sql(\'RM_DS\', \'Select STATUS From AW_JOBEXECUTION_DELTA Where NAME = {$JobName}\' );
        $JobStatus = nvl($JobStatus, \'none\');
		
		#print (\'DEBUG F.1 AW_CtrlJob --> status = {$JobStatus} per il job = {$JobName} \');
        if($JobStatus = \'failed\')
		    begin	
			    $dateDiff = sql(\'RM_DS\', \'Select (Case When (to_date(to_char(EXTRACTHIGH,\\\'yyyy.mm.dd hh24:mi:ss\\\'),\\\'yyyy.mm.dd hh24:mi:ss\\\') - to_date(to_char(EXTRACTLOW,\\\'yyyy.mm.dd hh24:mi:ss\\\'),\\\'yyyy.mm.dd hh24:mi:ss\\\')) < 0 Then -4 
		                                           Else 1 
										      End) 
								  From AW_JOBEXECUTION_DELTA Where NAME = {$JobName}\');
	            
		        if(($dateDiff = -4))
				    $ret = -4;
                else
				    begin
				    #imposto il valore di ritorno della funzione a KO per stato diverso da "done" 
				        $ret = -2;
	            
				    #print (\'****** ERROR --- Il job si trova in uno stato diverso da "done": JobStatus= \'|| $JobStatus || \' ******\');
				    #raise_exception(\'****** ERROR --- Rilevato uno stato del job non ammesso: \'|| $ret || \' ******\') ;
                    end 
            end 
			   
		if(($JobStatus != \'failed\') and ($JobStatus != \'done\'))
	        begin
				#imposto il valore di ritorno della funzione a KO per stato diverso da "done" 
				$ret = -1;
	     
		        #print (\'****** ERROR --- Il job si trova in uno stato diverso da "done": jobstatus= \'|| $jobstatus || \' ******\');
				#raise_exception(\'****** ERROR --- Rilevato uno stato del job non ammesso: \'|| $ret || \' ******\') ;
