# Verifico la coerenza delle date di estrazione della tabella AW_JOBEXECUTION_DELTA

try
	begin
 	    $dateDiff = sql(\'RM_DS\', \'Select (Case When (to_date(to_char(EXTRACTHIGH,\\\'yyyy.mm.dd hh24:mi:ss\\\'),\\\'yyyy.mm.dd hh24:mi:ss\\\') - to_date(to_char(EXTRACTLOW,\\\'yyyy.mm.dd hh24:mi:ss\\\'),\\\'yyyy.mm.dd hh24:mi:ss\\\')) < 0 Then -3 
		                                       Else 1 
										  End) 
								  From AW_JOBEXECUTION_DELTA Where NAME = {$JobName}\');

	    #print (\'DEBUG F.1 b AW_CtrlStatus -->  ExtractLOW=[$extractLOW]\');
	    #print (\'DEBUG F.2 b AW_CtrlStatus -->  ExtractHIGH=[$extractHIGH]\');
	    #print (\'DEBUG F.3 b AW_CtrlStatus -->  $dateDiff= [$dateDiff]\');
	    
		if(($dateDiff = 1) and ($ret = 0))
            begin
		        #imposto il valore di ritorno della funzione a OK 
			    #print (\'****** INFO ---  Date di estrazione Coerenti:StartDate ExtractLOW=\' || $extractlow || \'  >  EndDate = \' || $extracthigh  );
		        $ret = $dateDiff;
		    end

	   if(($dateDiff = -3) and ($ret = 0)) 
            begin
		        #imposto il valore di ritorno della funzione a KO per date non coerenti 
		        $ret = $dateDiff;
	            #print (\'****** ERROR ---  La StartDate ExtractLOW=\' || $extractlow || \'  > della EndDate= \' || $extracthigh  );
		    end

#	   if (	($dateDiff = -4)and ($ret=0)) 
#            begin
#		        #imposto il valore di ritorno della funzione a KO per date non coerenti 
#		        $ret = $dateDiff;
#	            #print (\'****** ERROR ---  La StartDate ExtractLOW=\' || $extractlow || \'= alla EndDate= \' || $extracthigh  );
#		    end
	          
	end

catch ( all )
	begin
		print (\'****** ERROR --- \'|| error_message() || \' ******\');
	end

# PRINT (\'DEBUG F.2 b AW_CtrlStatus -->  return code=[$ret]\');

return ($ret);



', "x" = '-1', "y" = '-1')
CREATE FUNCTION AW_CtrlJob($jobname VARCHAR(64)  IN )
RETURNS  INT 
DECLARE
     $ret INT ;
     $dateDiff INT ;
BEGIN
$ret = 0;TRY
BEGIN
$JobStatus = nvl($JobStatus, 'none');IF (($JobStatus = 'failed') )
BEGIN
$dateDiff = sql('RM_DS', 'Select (Case When (to_date(to_char(EXTRACTHIGH,\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\') - to_date(to_char(EXTRACTLOW,\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\')) < 0 Then -4 
		                                           Else 1 
										      End) 
								  From AW_JOBEXECUTION_DELTA Where NAME = {$JobName}');IF (($dateDiff = -4) )
$ret = -4;ELSE
BEGIN
$ret = -2;END
END
IF ((($JobStatus != 'failed') AND
   ($JobStatus != 'done')) )
BEGIN
$ret = -1;END
END
CATCH (210101)
BEGIN
print((('****** ERROR --- ' || error_message()) || ' ******'));END

END_TRY
TRY
BEGIN
$dateDiff = sql('RM_DS', 'Select (Case When (to_date(to_char(EXTRACTHIGH,\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\') - to_date(to_char(EXTRACTLOW,\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\')) < 0 Then -3 
		                                       Else 1 
										  End) 
								  From AW_JOBEXECUTION_DELTA Where NAME = {$JobName}');IF ((($dateDiff = 1) AND
   ($ret = 0)) )
BEGIN
$ret = $dateDiff;END
IF ((($dateDiff = -3) AND
   ($ret = 0)) )
BEGIN
$ret = $dateDiff;END
END
CATCH (210101)
BEGIN
print((('****** ERROR --- ' || error_message()) || ' ******'));END

END_TRY
RETURN $ret;
END
