CREATE FUNCTION AW_checkDateEstrazione($G_SDATE VARCHAR(19)  IN, $G_EDATE VARCHAR(19)  IN )
RETURNS  INT 
DECLARE
     $ret INT ;
     $ExtractLOW DATETIME(9) ;
     $ExtractHIGH DATETIME(9) ;
     $dateDiff INT ;
BEGIN
$ret = 0;$ExtractLOW =  NULL ;$ExtractHIGH =  NULL ;$ExtractLOW = sql('RM_DS', 'Select to_char(CheckDate({$G_SDATE},\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\') From DUAL');$ExtractHIGH = sql('RM_DS', 'Select to_char(CheckDate({$G_EDATE},\'yyyy.mm.dd hh24:mi:ss\'),\'yyyy.mm.dd hh24:mi:ss\') From DUAL');IF ((($ExtractLOW IS  NULL ) OR
   ($ExtractHIGH IS  NULL )) )
BEGIN
$ret = -1;END
ELSE
BEGIN
TRY
BEGIN
$dateDiff = sql('RM_DS', 'Select (Case When (to_date({$G_EDATE},\'yyyy.mm.dd hh24:mi:ss\') - to_date({$G_SDATE},\'yyyy.mm.dd hh24:mi:ss\')) = 0 Then -3 
				                                       When (to_date({$G_EDATE},\'yyyy.mm.dd hh24:mi:ss\') - to_date({$G_SDATE},\'yyyy.mm.dd hh24:mi:ss\')) < 0 Then -2 
												       Else 1 
												  End )
										  From DUAL');IF ((($dateDiff = 1) AND
   ($ret = 0)) )
BEGIN
$ret = $dateDiff;END
IF ((($dateDiff = -2) AND
   ($ret = 0)) )
BEGIN
$ret = $dateDiff;END
IF ((($dateDiff = -3) AND
   ($ret = 0)) )
BEGIN
$ret = $dateDiff;END
END
CATCH (210101)
BEGIN
print((('****** ERROR --- ' || error_message()) || ' ******'));END

END_TRY
END
RETURN $ret;
END
