return get_env(\'disk\');', "x" = '-1', "y" = '-1')
CREATE FUNCTION GET_DISK_LETTER( )
RETURNS  INT 
BEGIN
IF (((file_exists('D:\\7-zip') = 1) AND
   (index(upper(get_env('Path')), 'D:\\', 0) > 0)) )
set_env('disk', 'D:');ELSE
BEGIN
IF (((file_exists('E:\\7-zip') = 1) AND
   (index(upper(get_env('Path')), 'E:\\', 0) > 0)) )
set_env('disk', 'E:');ELSE
IF (((index(upper(get_env('Path')), 'D:\\', 0) > 0) AND
   (index(upper(get_env('Path')), 'E:\\', 0) IS  NULL )) )
set_env('disk', 'D:');ELSE
IF (((index(upper(get_env('Path')), 'E:\\', 0) > 0) AND
   (index(upper(get_env('Path')), 'D:\\', 0) IS  NULL )) )
set_env('disk', 'E:');ELSE
BEGIN
$quitresultcode = 1;$TempMessage = (('ATTENZIONE IL JOB ANDRA in ERRORE' || chr(13)) || 'Non e\' stato possibile individuare la lettera del disco locale');print('[$TempMessage]');$Error_number = 50316;$Error_message = 'Non e\' stato possibile individuare la lettera del disco locale';raise_exception_ext($TempMessage, $quitresultcode);END
END
RETURN get_env('disk');
END
