        $VAR_EXP = \'Update MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO Set DATA_ESECUZIONE=add_days(current_date,7) Where Flusso=\\\'[$sufFlusso]\\\' And Esito=\\\'0\\\' And FREQUENZA=\\\'[$Frequenza]\\\'\';
        #print($VAR_EXP);
