			end

	    catch ( all )
	        begin
		
	        end
    end


################################################################################
#  Caso di file prodotto non vuoto
################################################################################
else 
    begin
        # print(\'---> Creazione del file definitivo\');
        #print(\'Nome file flusso [$NomeFileFlusso]\');

        #-------------  rename file \'non vuoto\' di Flusso .temp in .csv   -------------#
	    try
            begin
                $VAR_EXP = \'IF EXIST "[$FolderOut][$FileNameTemp]" RENAME "[$FolderOut][$FileNameTemp]" [$NomeFileFlusso]\';
                #print(\'Rinomina del file [$VAR_EXP]\');
                exec(\'cmd\',$VAR_EXP,0);
                print(\'---> File End_Flusso [$NomeFileFlusso] generato\');
            end 

	    catch (all)
            begin
                $noquitresultcode = 1;
                print(\'---> Errore End_Flusso: File flusso [$FileNameTemp] non rinominato in [$NomeFileFlusso].\');
		
