        sql(\'MON_DATAMART_HANA\',$VAR_EXP);     
	end

catch ( all )
    begin
	    raise_exception( \'--> Errore nell\\\'inserimento nella tabella di TDB_LOG per il flusso [$sufFlusso]\');	
    end


#-------     aggiornamento nella tabella configurazione corretta esecuzione del flusso     -------#
try
  begin     
    if($TipoEsecuzione = \'M\') 
	   begin
        $VAR_EXP = \'DELETE FROM MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO WHERE DATA_ESECUZIONE=current_date And FLUSSO=\\\'[$sufFlusso]\\\' And FREQUENZA=\\\'[$Frequenza]\\\' And  TIPO_ESECUZIONE = \\\'[$TipoEsecuzione]\\\'\';
		sql(\'MON_DATAMART_HANA\',$VAR_EXP);
	   end
   
     if($TipoEsecuzione = \'S\')
	   begin
		# $VAR_EXP = \'Update  MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO SET Esito=\\\'1\\\',DATA_ESECUZIONE=current_date,DAta_Agg=current_date Where FLUSSO=\\\'[$sufFlusso]\\\' And DATA_ESECUZIONE=current_date And FREQUENZA=\\\'[$Frequenza]\\\'\';
        $VAR_EXP = \'Update  MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO SET Esito=\\\'1\\\',DATA_ESECUZIONE=current_date,DAta_Agg=current_date Where FLUSSO=\\\'[$sufFlusso]\\\' And DATA_ESECUZIONE=current_date And FREQUENZA=\\\'[$Frequenza]\\\' And  TIPO_ESECUZIONE = \\\'[$TipoEsecuzione]\\\'\';
