        $VAR_EXP = \'Update MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO Set DATA_ESECUZIONE=add_days(current_date,7) Where Flusso=\\\'[$sufFlusso]\\\' And Esito=\\\'0\\\' And FREQUENZA=\\\'[$Frequenza]\\\'\';
        #print($VAR_EXP);
	    #print(\'Inseriemnto tabella di configurazione  effettuato dalla procedura e Update della data eseguita al termine dell\\\'esecuzione del file  \'||$VAR_EXP);
        sql(\'MON_DATAMART_HANA\',$VAR_EXP);     
    end
end
catch ( all )
    begin
	    raise_exception( \'--> Errore nell\\\'inserimento nella tabella MON_DATAMART.TABLEAU_ESECUZIONE_FLUSSO per il flusso [$sufFlusso] con frequenza [$frequenza]\');	
    end


