    begin   
        if($TipoEsecuzione = \'S\') 
            begin
                #aggiorno nella tabella di configurazione l\'ultima week eseguita solo se esecuzione schedulata  
                $VAR_EXP = \'Update MON_DATAMART.TABLEAU_CONFIG_FLUSSO Set PARA_INPUT=\\\'[$ParametroSP]\\\' Where Flusso=\\\'[$sufFlusso]\\\' And  FREQUENZA=\\\'[$frequenza]\\\'\';
                #print($VAR_EXP);
                sql(\'MON_DATAMART_HANA\',$VAR_EXP);
            end
    end

catch ( all )
    begin
