CREATE PLAN WF_TableauDeBord_Pind::'785932ba-5d35-426b-8632-b499883b5837'( )
BEGIN
 AlGUIComment ("UI_DATA_XML" = '<UIDATA><MAINICON><LOCATION><X>0</X><Y>0</Y></LOCATION><SIZE><CX>222</CX><CY>-179</CY></SIZE></MAINICON><DESCRIPTION><LOCATION><X>0</X><Y>-191</Y></LOCATION><SIZE><CX>200</CX><CY>200</CY></SIZE><VISIBLE>0</VISIBLE></DESCRIPTION></UIDATA>', "ui_display_name" = 'InitializeJob', "ui_script_text" = '################################################################################
#            system environment variables per la durata del job
################################################################################

Get_disk_letter();
print (\'**** Nome del disco locale = \' || get_env(\'disk\'));


######################################################
###       Parametri per invio messaggio SMTP       ### 
######################################################

#Valore relativo al mandante dell\'eventuale messaggio SMTP
$Sender = sql(\'RM_DS\', \'Select Sender From Message_SMTP Where Jobname = {$jobname}\' );

#Valore relativo al ricevitore dell\'eventuale messaggio SMTP
$Admin  = sql(\'RM_DS\', \'Select Admin  From Message_SMTP Where Jobname = {$jobname}\' );

#Valore relativo al cliente ricevitore dell\'eventuale messaggio SMTP
$Client = sql(\'RM_DS\', \'Select Client From Message_SMTP Where Jobname = {$jobname}\' );

#Valore flag per eventuale messaggio SMTP Receiver\\Admin su OK
$OK_Adm = sql(\'RM_DS\', \'Select OK_Adm From Message_SMTP Where Jobname = {$jobname}\' );

#Valore flag per eventuale messaggio SMTP Receiver\\Admin su KO
$KO_Adm = sql(\'RM_DS\', \'Select KO_Adm From Message_SMTP Where Jobname = {$jobname}\' );

#Valore flag per eventuale messaggio SMTP Cliente su OK
$OK_Cli = sql(\'RM_DS\', \'Select OK_Cli From Message_SMTP Where Jobname = {$jobname}\' );

#Valore flag per eventuale messaggio SMTP Cliente su KO
$KO_Cli = sql(\'RM_DS\', \'Select KO_Cli From Message_SMTP Where Jobname = {$jobname}\' );


print( \'-->  JobName:  [$JobName]\');
print( \'-->  Sender:   [$Sender]\');
print( \'-->  Receiver: [$Admin]\');


#################################################
##   Salvo le date di estrazione dell\'ultima   ##
###     esecuzione correttamente eseguita     ###
#################################################

$G_SDATE_bck = AW_getStartDate(job_name());
$G_EDATE_bck = AW_getEndDate(job_name()); 


#################################################
###  3.    Verifica dello stato del job       ### 
#################################################
# La funzione ritorna :
# $ret= -4 vale KO : se la date extractlow = extracthigh   --> il job non deve essere eseguito
# $ret= -3 vale KO : se la date extractlow > extracthigh   --> il job non deve essere eseguito
# $ret= -2 vale KO : se lo stato del job e\' \'failed\'  --> il job viene eseguito con le date della precedente esecuzione
# $ret= -1 vale KO : se lo stato del job e\' diverso da done e da failed (started, none, altra stringa)
# $ret=  1 vale OK : se lo stato del job e\'  \'done\' e se la date extractlow < extracthigh  --> il job puo\' essere eseguito 

$flagCtrlFunction = AW_CtrlJob(job_name());
#print(\'FlagCTRL = \'|| $flagCtrlFunction); 

if($flagCtrlFunction = -1)
    begin
        print (\'****** ERROR --- Il job si trova in uno stato diverso da "done" e da "failed"  ******\');
        raise_exception(\'****** ERROR ---  Il job si trova in uno stato diverso da "done":  ******\');
    end 

if($flagCtrlFunction = -3)
    begin
        print (\'****** ERROR --- StartDate (ExtractLOW)  >  EndDate (ExtractHIGH) nella tabella AW_JOBEXECUTION_DELTA\');
        raise_exception(\'****** ERROR ---  StartDate (ExtractLOW)  >  EndDate (ExtractHIGH) nella tabella AW_JOBEXECUTION_DELTA\');
    end 


if($flagCtrlFunction = -4)
    begin
        print (\'****** ERROR --- StartDate(ExtractLOW)  =  EndDate(ExtractHIGH) nella tabella AW_JOBEXECUTION_DELTA\');
        raise_exception(\'****** ERROR ---  StartDate (ExtractLOW)  =  EndDate (ExtractHIGH) nella tabella AW_JOBEXECUTION_DELTA\');
    end 

if($flagCtrlFunction = -2)
    print (\'****** INFO --- Il job si trova nello stato "failed", VERRA\\\' riestratto il precedente intervallo di date\');

if($flagCtrlFunction = 1)
    print (\'****** INFO il job si trova nello stato "done", coerente per la corrente esecuzione: \');


################################################################################
# 4.a Verifico se si tratta di un recupero o di un nuovo itervallo di estrazione
################################################################################
# se le variabili globali sono valorizzate si tratta di un recupero. 
# In questo caso le date non vengono valorizzate sulla base dell\'ultima esecuzione


#================================================================================================
# [Function:AW_checkRecupero] 
#Verifica se si tratta di un aesecuzione per un recupero "spot" di un intervallo di date specifico
#
# La funzione ritorna:
#$ret=  1 - E\' un recupero delle date specificate nelle variabili globali
#$ret=  0 - NON E\' un recupero.
#=============================================================================

$flagCtrlFunction = 999;

$flagCtrlFunction = AW_checkRecupero($G_SDATE_RECUPERO, $G_EDATE_RECUPERO);
if($flagCtrlFunction = 0)
    begin
	    #imposto gli intervalli superiore e inferiore di estrazione dell\'esecuzione corrente
	    #se lo stato dell\'esecuzione precedente e\' "done" calcolo le nuove date di estrazione
	    #se lo stato del job e\' failed ripeto l\'estrazione precedente.
	    if($JobStatus = \'done\')
	        begin
	            $G_SDATE_NEW = $G_EDATE_bck;
	            $G_EDATE = sysdate(); 
            end
	    else
	    #stato = \'failed\' ripeto l\'estrazione precedente con le Date EXTRACTLOW e EXTRACTHIGH della tabella AW_JOBEXECUTION_DELTA
	        begin
		        $G_SDATE_NEW = $G_EDATE_bck;
	            $G_EDATE = $G_EDATE_bck; 
            end
    end  
 
else 
    # si tratta di un recupero con le variabili globali valorizzate
    #================================================================================================
    # [Function:AW_checkDateEstrazione] 
    # Controlla il formato e la validita\' delle stringhe nelle variabili "$G_SDATE input, $G_EDATE 
    # e che l\'intervallo di estrazione disa coerente: $G_SDATE > $G_EDATE
    #
    # La funzione ritorna:
    #  1 per OK
    # -1 per formato DATA delle stringhe passate alla funzione non valido
    # -2 per DATE non coerenti per esecuzione job: $G_SDATE > $G_EDATE
    # -3 per DATE non coerenti per esecuzione job: $G_SDATE = $G_EDATE
    #=============================================================================
    begin
	    $flagCtrlFunction = 999;
        $flagCtrlFunction = AW_checkDateEstrazione($G_SDATE_RECUPERO, $G_EDATE_RECUPERO);
		print (\'****** INFO --- Verifico le date impostate per il recupero  ******\');
        
		if($flagCtrlFunction = -1)
            begin
                print (\'****** ERROR --- Le date $G_SDATE_RECUPERO e $G_EDATE_RECUPERO non sono nel formato consentito  ******\');
                raise_exception(\'****** ERROR --- Le date $G_SDATE_RECUPERO e $G_EDATE_RECUPERO non sono nel formato consentito  ******\');
            end 
        
		if($flagCtrlFunction = -2)
            begin
                print (\'****** ERROR --- $G_SDATE_RECUPERO>$G_EDATE_RECUPERO \');
                raise_exception(\'****** ERROR --- $G_SDATE_RECUPERO>$G_EDATE\');
            end

        if($flagCtrlFunction = -3)
            begin
                print (\'****** ERROR --- $G_SDATE_RECUPERO=$G_EDATE_RECUPERO \');
                raise_exception(\'****** ERROR --- $G_SDATE_RECUPERO=$G_EDATE_RECUPERO\');
            end
			 
        if($flagCtrlFunction = 1)
            begin
			    $G_EDATE = $G_EDATE_RECUPERO;
                $G_SDATE_NEW = $G_SDATE_RECUPERO;
                print (\'****** INFO Le date $G_SDATE_RECUPERO e $G_EDATE_RECUPERO valorizzate nelle variabili  per il RECUPERO sono valide  ******\');
            end 
    end	            


#####################################################################################
# 5. Imposto lo status del job a "started" e valorizzo la LOAD_DATE a currentimestamp  
#####################################################################################
#imposto lo status a "started"
$flagCtrlFunction = AW_setJobStatus(job_name(),\'started\');
       
#controllo l\'esito della funzione 
